// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title PackedSerializer
 * @notice Efficient serialization library for cross-chain message passing
 * @dev Uses tight packing with length-prefixed fields for gas optimization
 */
library PackedSerializer {
    uint256 private constant WORD_SIZE = 32;
    uint256 private constant MAX_PAYLOAD_WORDS = 256;
    uint256 private constant HEADER_SIZE = 4; // 4 bytes for length prefix
    uint256 private constant MAX_FIELD_LEN = 0xFFFF; // 2-byte length prefix limit

    struct SerializationContext {
        bytes buffer;
        uint256 writeOffset;
        uint256 capacity;
        bool finalized;
    }

    function createContext(uint256 maxWords) internal pure returns (SerializationContext memory ctx) {
        require(maxWords <= MAX_PAYLOAD_WORDS, "Exceeds max payload");
        uint256 totalCapacity = maxWords * WORD_SIZE + HEADER_SIZE;
        ctx.buffer = new bytes(totalCapacity);
        ctx.writeOffset = HEADER_SIZE; // Reserve space for length header
        ctx.capacity = totalCapacity;
        ctx.finalized = false;
    }

    /**
     * @dev Appends a dynamic-length field to the serialization buffer
     * @param ctx The serialization context
     * @param data The bytes to append
     * @return remainingCapacity The remaining buffer capacity after write
     */
    function appendField(
        SerializationContext memory ctx,
        bytes memory data
    ) internal pure returns (uint256 remainingCapacity) {
        require(!ctx.finalized, "Context finalized");

        // Calculate padded length (round up to word boundary)
        uint256 dataLen = data.length;
        // Ensure the length fits in the 2-byte length prefix to avoid
        // silent truncation and data corruption on deserialize.
        require(dataLen <= MAX_FIELD_LEN, "Field too large");
        uint256 paddedLen = ((dataLen + WORD_SIZE - 1) / WORD_SIZE) * WORD_SIZE;

        // Field format: [2-byte length][padded data]
        uint256 fieldSize = 2 + paddedLen;

        // Bounds check: verify we won't exceed capacity
        uint256 newOffset = ctx.writeOffset + fieldSize;
        require(newOffset <= ctx.capacity, "Buffer overflow");

        // Write length prefix (2 bytes, big-endian)
        bytes memory buf = ctx.buffer;
        uint256 offset = ctx.writeOffset;

        assembly {
            let bufPtr := add(buf, 32) // skip length prefix of bytes
            let writePos := add(bufPtr, offset)

            // Store 2-byte length
            mstore8(writePos, shr(8, dataLen))
            mstore8(add(writePos, 1), and(dataLen, 0xff))

            // Copy data word by word
            let src := add(data, 32)
            let dst := add(writePos, 2)
            for { let i := 0 } lt(i, paddedLen) { i := add(i, 32) } {
                mstore(add(dst, i), mload(add(src, i)))
            }
        }

        ctx.writeOffset = newOffset;
        remainingCapacity = ctx.capacity - newOffset;
    }

    /**
     * @dev Appends multiple fields from an array in batch mode
     * @param ctx The serialization context  
     * @param fields Array of byte arrays to serialize
     * @return totalWritten Total bytes written across all fields
     */
    function batchAppend(
        SerializationContext memory ctx,
        bytes[] memory fields
    ) internal pure returns (uint256 totalWritten) {
        uint256 startOffset = ctx.writeOffset;

        for (uint256 i = 0; i < fields.length; i++) {
            // Pre-check: calculate cumulative size needed
            uint256 dataLen = fields[i].length;
            uint256 paddedLen = ((dataLen + WORD_SIZE - 1) / WORD_SIZE) * WORD_SIZE;
            uint256 fieldSize = 2 + paddedLen;

            // Use unchecked arithmetic for gas optimization
            // The individual appendField call will do the bounds check
            unchecked {
                totalWritten += fieldSize;
            }

            appendField(ctx, fields[i]);
        }

        // Verify consistency
        assert(ctx.writeOffset - startOffset == totalWritten);
    }

    /**
     * @dev Deserializes a buffer back into individual fields
     * @param packed The packed buffer (including 4-byte header)
     * @return fields The deserialized field array
     */
    function deserialize(
        bytes memory packed
    ) internal pure returns (bytes[] memory fields) {
        require(packed.length >= HEADER_SIZE, "Invalid packed data");

        // Read number of fields from header
        uint256 numFields;
        assembly {
            numFields := shr(224, mload(add(packed, 32)))
        }

        fields = new bytes[](numFields);
        uint256 readOffset = HEADER_SIZE;

        for (uint256 i = 0; i < numFields; i++) {
            require(readOffset + 2 <= packed.length, "Truncated field header");

            // Read 2-byte length
            uint256 fieldLen;
            assembly {
                let ptr := add(add(packed, 32), readOffset)
                fieldLen := and(shr(240, mload(ptr)), 0xffff)
            }

            uint256 paddedLen = ((fieldLen + WORD_SIZE - 1) / WORD_SIZE) * WORD_SIZE;

            // Critical: validate read won't exceed buffer using paddedLen
            require(readOffset + 2 + paddedLen <= packed.length, "Field exceeds buffer");

            bytes memory field = new bytes(fieldLen);
            assembly {
                let src := add(add(packed, 32), add(readOffset, 2))
                let dst := add(field, 32)
                // Copy only fieldLen bytes to avoid writing past allocation
                for { let j := 0 } lt(j, fieldLen) { j := add(j, 32) } {
                    mstore(add(dst, j), mload(add(src, j)))
                }
            }

            // Advance read pointer by field header + padded data
            unchecked {
                readOffset += 2 + paddedLen;
            }

            fields[i] = field;
        }
    }

    /**
     * @dev Finalizes the context and writes the field count header
     * @param ctx The serialization context
     * @param fieldCount Number of fields written
     * @return result The finalized packed bytes
     */
    function finalize(
        SerializationContext memory ctx,
        uint256 fieldCount
    ) internal pure returns (bytes memory result) {
        require(!ctx.finalized, "Already finalized");
        ctx.finalized = true;

        bytes memory buf = ctx.buffer;

        // Write 4-byte header with field count
        assembly {
            let bufPtr := add(buf, 32)
            mstore(bufPtr, shl(224, fieldCount))
        }

        // Trim buffer to actual written size
        uint256 actualSize = ctx.writeOffset;
        result = new bytes(actualSize);
        assembly {
            let src := add(buf, 32)
            let dst := add(result, 32)
            for { let i := 0 } lt(i, actualSize) { i := add(i, 32) } {
                mstore(add(dst, i), mload(add(src, i)))
            }
        }
    }
}

/**
 * @title CrossChainBridge
 * @notice Uses PackedSerializer for encoding cross-chain messages
 */
contract CrossChainBridge {
    using PackedSerializer for PackedSerializer.SerializationContext;

    event MessageSent(bytes32 indexed messageHash, bytes payload);

    mapping(bytes32 => bool) public processedMessages;

    function sendMessage(
        address target,
        bytes calldata payload,
        uint256 nonce
    ) external returns (bytes32 messageHash) {
        PackedSerializer.SerializationContext memory ctx = PackedSerializer.createContext(16);

        bytes memory addrBytes = abi.encodePacked(msg.sender, target);
        bytes memory nonceBytes = abi.encodePacked(nonce);

        ctx.appendField(addrBytes);
        ctx.appendField(payload);
        ctx.appendField(nonceBytes);

        bytes memory packed = PackedSerializer.finalize(ctx, 3);
        messageHash = keccak256(packed);

        emit MessageSent(messageHash, packed);
    }

    function processMessage(bytes calldata packed) external {
        bytes32 msgHash = keccak256(packed);
        require(!processedMessages[msgHash], "Already processed");
        processedMessages[msgHash] = true;

        bytes[] memory fields = PackedSerializer.deserialize(packed);
        require(fields.length == 3, "Invalid message format");

        // Process decoded fields...
    }
}
